const $=s=>document.querySelector(s);
export class VoiceController{
 constructor(opts){Object.assign(this,opts);this.mode='local';this.state='idle';this.stream=null;this.pc=null;this.dc=null;this.recognition=null;this.muted=false;this.timer=null;this.speaking=false;this.generation=0;this.seenTools=new Set();this.transcripts=new Map();this.metrics={};this.retryCount=0;this.bind();const stop=document.createElement('button');stop.textContent='停止播报';stop.id='stopSpeaking';stop.onclick=()=>this.interrupt();$('#callPanel .call-controls').append(stop);this.addMessage('assistant','我在，五简。你可以让我扫描机会、分析品种、检查风险。当前是本地固定指令体验，价格和图表均为演示数据。')}
 bind(){$('#minCall').onclick=()=>{ $('#callPanel').hidden=true;$('#floatingCall').hidden=false;$('#floatingCall').firstChild.textContent=this.state==='connected'?'◉ 通话中 ':'◉ 对话已收起 '};$('#floatingCall').onclick=()=>this.open();$('#localMode').onclick=()=>this.setMode('local');$('#aiMode').onclick=()=>this.setMode('ai');$('#connectCall').onclick=()=>{this.retryCount=0;this.connect()};$('#muteCall').onclick=()=>this.mute();$('#hangup').onclick=()=>{this.stop();this.addMessage('assistant','通话已结束。已提交的研究任务仍可在本地工作队列中查看。')};$('#chatForm').onsubmit=e=>{e.preventDefault();let text=$('#chatInput').value.trim();if(!text)return;$('#chatInput').value='';this.submit(text)};document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>this.submit(b.dataset.prompt))}
 open(){$('#callPanel').hidden=false;$('#floatingCall').hidden=true;$('#chatInput').focus()}
 setMode(m){if(this.state!=='idle')this.stop();this.mode=m;$('#localMode').classList.toggle('active',m==='local');$('#aiMode').classList.toggle('active',m==='ai');$('#voiceNote').textContent=m==='local'?'本地模式识别固定指令；语音识别可能由浏览器服务处理。':'AI语音将发送至配置的服务；通话中可启动本地研究任务。';this.status(m==='local'?'文字模式 · 本地指令助手':this.isConfigured()?'AI通话就绪 · 点击接通':'AI语音待配置 · 本地文字仍可用')}
 status(text){$('#callStatus').textContent=text;document.body.dataset.voiceState=this.speaking?'speaking':this.state}
 addMessage(role,text){const d=document.createElement('div');d.className='bubble '+(role==='user'?'user':'');const s=document.createElement('small');s.textContent=role==='user'?'你':'JARVIS';const p=document.createElement('span');p.textContent=text;d.append(s,p);$('#messages').append(d);$('#messages').scrollTop=$('#messages').scrollHeight;return p}
 async submit(text){if(/^(停一下|停止播报|别说了)[。！!]?$/u.test(text.trim())){this.interrupt();return}this.addMessage('user',text);if(this.mode==='ai'&&this.dc?.readyState==='open'){this.send({type:'conversation.item.create',item:{type:'message',role:'user',content:[{type:'input_text',text}]}});this.send({type:'response.create'});return}if(this.mode==='ai'){this.addMessage('assistant','AI通话尚未连接。请先接通，或切到本地体验运行指令。');return}const before=$('#messages').childElementCount;const answer=await this.command(text);if($('#messages').childElementCount===before)this.addMessage('assistant',answer);if(this.state==='connected')this.speak(answer)}
 async connect(){if(this.state!=='idle')return;this.open();if(this.mode==='ai'&&!this.isConfigured()){this.status('AI实时通话尚未配置');this.addMessage('assistant','请在本机服务端的 .env 配置 OPENAI_API_KEY 后重启。不要把密钥发到对话或填写进网页。现在可以切换到本地体验。');return}if(this.mode==='local'&&!(window.SpeechRecognition||window.webkitSpeechRecognition)){this.status('此浏览器不支持语音识别');this.addMessage('assistant','当前浏览器未提供语音识别。文字指令可以继续使用；也可在支持语音识别的浏览器中打开本地地址。');return}this.metrics.connectStarted=performance.now();this.state='connecting';this.status('正在请求麦克风…');$('#connectCall').disabled=true;let gen=++this.generation;try{const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true}});if(gen!==this.generation){stream.getTracks().forEach(t=>t.stop());return}this.stream=stream;if(this.mode==='local')this.startLocal();else await this.startRealtime(gen)}catch(e){if(gen!==this.generation)return;this.stop();this.status(e.name==='NotAllowedError'?'麦克风权限未授予':'语音连接失败');this.addMessage('assistant',e.name==='NotAllowedError'?'浏览器没有授予麦克风权限。可允许后重试，或继续文字交互。':e.message||'连接失败，请继续文字交互。')}}
 connected(){clearTimeout(this.connectTimeout);clearTimeout(this.reconnectTimer);clearInterval(this.timer);this.metrics.connectMs=Math.round(performance.now()-this.metrics.connectStarted);this.state='connected';this.started=Date.now();this.status(this.mode==='local'?'已连接 · 本地语音指令':'已连接 · AI实时通话');$('#connectCall').textContent='通话已接通';$('#muteCall').disabled=false;this.timer=setInterval(()=>{let t=Math.floor((Date.now()-this.started)/1000);$('#callTime').textContent=String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');if(t>=900){this.stop();this.addMessage('assistant','通话达到15分钟，已结束。可重新接通。')}},1000)}
 startLocal(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;this.recognition=new SR();this.recognition.lang='zh-CN';this.recognition.continuous=true;this.recognition.interimResults=false;this.recognition.onresult=e=>{if(this.speaking||this.muted)return;const result=e.results[e.resultIndex];if(result.isFinal)this.submit(result[0].transcript)};this.recognition.onerror=e=>{if(['not-allowed','service-not-allowed','network','audio-capture'].includes(e.error)){this.stop();this.status('语音识别不可用 · 文字仍可用');this.addMessage('assistant','浏览器语音识别服务不可用（'+e.error+'）。没有将它伪装成通话成功；你可以继续文字操作。')}};this.recognition.onend=()=>{if(this.state==='connected'&&!this.muted&&!this.speaking)setTimeout(()=>{try{this.recognition?.start()}catch{}},350)};this.recognition.start();this.connected();this.speak('我在，五简。你可以一边和我说话，一边查看工作台。当前使用演示数据。')}
 speak(text){if(!window.speechSynthesis||this.state!=='connected')return;this.speaking=true;document.body.dataset.voiceState="speaking";try{this.recognition?.stop()}catch{};speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='zh-CN';u.rate=1.03;u.onend=u.onerror=()=>{this.speaking=false;document.body.dataset.voiceState=this.state;if(this.state==='connected'&&!this.muted){try{this.recognition?.start()}catch{}}};speechSynthesis.speak(u)}
 send(event){if(this.dc?.readyState==='open')this.dc.send(JSON.stringify(event))}
 async startRealtime(gen){const pc=this.pc=new RTCPeerConnection();this.remoteAudio=new Audio();this.remoteAudio.autoplay=true;pc.ontrack=e=>{if(gen!==this.generation)return;this.remoteAudio.srcObject=e.streams[0];this.remoteAudio.play().catch(()=>this.toast('请点击页面以允许播放语音'))};this.stream.getTracks().forEach(t=>pc.addTrack(t,this.stream));const dc=this.dc=pc.createDataChannel('oai-events');dc.onopen=()=>{if(gen!==this.generation)return;this.connected();this.send({type:'response.create',response:{instructions:'用一句简短中文问候五简，说明可以边对话边做本地演示研究。'}})};dc.onmessage=e=>{if(gen!==this.generation)return;try{this.onEvent(JSON.parse(e.data),gen)}catch{}};pc.onconnectionstatechange=()=>{if(gen!==this.generation)return;if(['failed','disconnected','closed'].includes(pc.connectionState)&&this.state!=='idle'){this.reconnect(gen)}};await pc.setLocalDescription(await pc.createOffer());if(pc.iceGatheringState!=='complete')await new Promise(resolve=>{const timeout=setTimeout(resolve,2500);pc.addEventListener('icegatheringstatechange',()=>{if(pc.iceGatheringState==='complete'){clearTimeout(timeout);resolve()}},{once:false})});if(gen!==this.generation)return;const controller=this.abort=new AbortController();const timeout=setTimeout(()=>controller.abort(),35000);let r;try{r=await fetch('/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sdp:pc.localDescription.sdp}),signal:controller.signal})}finally{clearTimeout(timeout)}if(!r.ok){let j=await r.json();throw Error(j.error||'语音连接失败')}const sdp=await r.text();if(gen!==this.generation)return;await pc.setRemoteDescription({type:'answer',sdp});this.connectTimeout=setTimeout(()=>{if(gen===this.generation&&this.state==='connecting'){this.stop();this.status('语音连接超时')}},15000)}
 phase(value){const labels={listening:'聆听中',user_speaking:'你正在说话',thinking:'正在处理',working:'正在查询工具',speaking:'正在播报'};this.status(this.muted?'麦克风已静音 · 后台任务继续':labels[value]||value);document.body.dataset.voiceState=this.muted?'muted':value}
 interrupt(){this.send({type:'response.cancel'});this.send({type:'output_audio_buffer.clear'});window.speechSynthesis?.cancel();this.speaking=false;if(this.state==='connected')this.phase('listening');this.metrics.lastInterruptAt=Date.now()}
 reconnect(gen){if(gen!==this.generation||this.reconnectTimer)return;this.reconnectTimer=setTimeout(async()=>{this.reconnectTimer=null;if(gen!==this.generation||this.pc?.connectionState==='connected')return;const attempt=this.retryCount+1;this.stop();if(attempt>2){this.status('重连失败 · 请手动接通');return}this.retryCount=attempt;this.addMessage('assistant','连接中断，正在建立新会话。已有任务继续；旧对话不会自动重放。');await this.connect()},1500)}
 transcript(e,role,done=false){const key=role+':'+(e.item_id||e.response_id||'current');let p=this.transcripts.get(key);if(!p){p=this.addMessage(role,'');this.transcripts.set(key,p)}p.textContent=done?e.transcript:(p.textContent+(e.delta||''));$('#messages').scrollTop=$('#messages').scrollHeight}
 async onEvent(e,gen=this.generation){if(gen!==this.generation)return;
 if(e.type==='input_audio_buffer.speech_started'){this.phase('user_speaking');this.metrics.userStarted=performance.now()}
 if(e.type==='input_audio_buffer.speech_stopped'){this.phase('thinking');this.metrics.userStopped=performance.now()}
 if(e.type==='output_audio_buffer.started'){this.phase('speaking');if(this.metrics.userStopped)this.metrics.responseMs=Math.round(performance.now()-this.metrics.userStopped)}
 if(e.type==='output_audio_buffer.stopped'||e.type==='output_audio_buffer.cleared')this.phase('listening');
 if(e.type==='response.output_audio_transcript.delta'||e.type==='response.audio_transcript.delta')this.transcript(e,'assistant');
 if(e.type==='conversation.item.input_audio_transcription.delta')this.transcript(e,'user');
 if(e.type==='response.output_audio_transcript.done'||e.type==='response.audio_transcript.done')this.transcript(e,'assistant',true);if(e.type==='conversation.item.input_audio_transcription.completed')this.transcript(e,'user',true);if(e.type==='error')this.addMessage('assistant','语音服务报告错误，请重试；已提交任务不受影响。');if(e.type==='response.function_call_arguments.done'){if(this.seenTools.has(e.call_id))return;this.seenTools.add(e.call_id);this.phase('working');try{const args=JSON.parse(e.arguments);const result=await this.api('/api/tool',{name:e.name,args});if(gen!==this.generation)return;this.addMessage('assistant',result.result?.summary||result.summary||result.error||('工具已返回：'+e.name+(result.id?' · 任务 '+result.id:'')));this.phase('thinking');this.send({type:'conversation.item.create',item:{type:'function_call_output',call_id:e.call_id,output:JSON.stringify(result)}});this.send({type:'response.create'});await this.onTool()}catch{if(gen!==this.generation)return;this.send({type:'conversation.item.create',item:{type:'function_call_output',call_id:e.call_id,output:JSON.stringify({error:'工具调用失败，未执行交易'})}});this.send({type:'response.create'})}}}
 mute(){this.muted=!this.muted;this.stream?.getAudioTracks().forEach(t=>t.enabled=!this.muted);if(this.mode==='local'){try{if(this.muted)this.recognition?.stop();else if(!this.speaking)this.recognition?.start()}catch{}}$('#muteCall').textContent=this.muted?'解除静音':'静音';this.status(this.muted?'麦克风已静音 · 后台任务继续':'已连接 · 可以继续对话')}
 stop(){this.generation++;clearTimeout(this.reconnectTimer);this.reconnectTimer=null;this.transcripts.clear();this.state='idle';this.abort?.abort();clearInterval(this.timer);clearTimeout(this.connectTimeout);if(this.recognition){this.recognition.onend=null;this.recognition.onerror=null;this.recognition.onresult=null;try{this.recognition.stop()}catch{};this.recognition=null}this.stream?.getTracks().forEach(t=>t.stop());this.stream=null;if(this.pc){this.pc.onconnectionstatechange=null;this.pc.ontrack=null}if(this.dc){this.dc.onopen=null;this.dc.onmessage=null;this.dc.close()}this.dc=null;this.pc?.close();this.pc=null;this.remoteAudio?.pause();if(this.remoteAudio)this.remoteAudio.srcObject=null;window.speechSynthesis?.cancel();this.speaking=false;this.muted=false;$('#connectCall').disabled=false;$('#connectCall').textContent='♧ 接通语音';$('#muteCall').disabled=true;$('#muteCall').textContent='静音';$('#callTime').textContent='00:00';this.status('通话已结束 · 文字仍可用');$('#floatingCall').firstChild.textContent='◉ 返回对话 ';}
}
